const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const rows = [];
for (const it of $('Read task queues (public repo)').all()) {
  const j = it.json;
  try {
    if (Array.isArray(j)) rows.push(...j);
    else if (j && typeof j.data === 'string') rows.push(...JSON.parse(j.data));
    else if (j && j.id && j.status) rows.push(j);
  } catch (e) {}
}
const now = $now.toMillis(), DAY = 864e5;
const today = rows.filter((r) => r.updated && now - new Date(r.updated).getTime() < DAY && r.status !== 'todo');
const passed = today.filter((r) => r.status === 'review' || r.status === 'done');
const back = today.filter((r) => r.status === 'rejected');
const count = (s) => rows.filter((r) => r.status === s).length;
const todo = count('todo'), review = count('review'), done = count('done');
const by = {};
for (const r of today) { const a = r.owner || 'Kalpa'; by[a] = by[a] || { ok: 0, redo: 0 }; if (r.status === 'rejected') by[a].redo++; else by[a].ok++; }
const team = Object.entries(by).sort((a, b) => (b[1].ok + b[1].redo) - (a[1].ok + a[1].redo));
let commits = [];
try { commits = $('GitHub commits (24 h)').all().map((i) => i.json).filter((c) => c && c.commit).map((c) => c.commit.message.split('\n')[0].slice(0, 70)); } catch (e) {}
let site = false;
try { site = ($('Site check').first().json.statusCode || 0) === 200; } catch (e) {}
const L = [];
L.push('<b>Kalpa Labs, ' + esc($now.setZone('Asia/Kolkata').toFormat('dd LLL')) + ' at 9 PM</b>');
L.push('Website: ' + (site ? 'up' : 'NOT answering'));
L.push('');
L.push('<b>Free-model agents, last 24 h</b>: ' + passed.length + ' jobs finished, ' + back.length + ' sent back');
for (const [a, c] of team.slice(0, 5)) L.push('  ' + esc(a) + ': ' + c.ok + ' done' + (c.redo ? ', ' + c.redo + ' sent back' : ''));
L.push('');
L.push('<b>Queue now</b>: ' + todo + ' waiting for agents, ' + review + ' waiting for Claude to check, ' + done + ' fully done');
if (todo === 0) L.push('The agent queue is empty, so agents are idle until the next build sprint adds jobs.');
L.push('');
L.push('<b>Code changes, last 24 h</b>: ' + commits.length);
for (const c of commits.slice(0, 3)) L.push('  ' + esc(c));
L.push('');
L.push(rows.length ? 'Nothing here needs you tonight.' : 'Could not read the task queues from GitHub. Claude checks this in the next sprint.');
return [{ json: { text: L.join('\n').slice(0, 3900) } }];
